<?php
require __DIR__.'/../admin.php';if(!admin_can('app_settings','update')){http_response_code(403);exit('Permission denied.');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sc_save_festival($_POST);header('Location: ./?saved=1',true,303);exit;}catch(Throwable $e){$error=$e instanceof mysqli_sql_exception?'Could not save festive mode.':$e->getMessage();}}$config=sc_festival_config(false);admin_console_open('Festive Season');
?>
<p>Celebrate on the homepage with festival-specific decorations and click effects. This is a manual switch; it does not calculate festival dates or turn itself on automatically.</p><?php if(isset($_GET['saved'])): ?><p class="alert alert-success" role="status">Festive mode saved.</p><?php endif; ?><?php if($error): ?><p class="alert alert-danger" role="alert"><?= sc_e($error) ?></p><?php endif; ?><div class="row g-4"><div class="col-lg-7"><form method="post" class="card p-4"><?= sc_token() ?><label class="mb-4"><input type="checkbox" name="enabled" <?= $config['enabled']?'checked':'' ?>> Enable festive mode on the homepage</label><label class="d-block mb-3">Festival<select class="form-select" name="festival" id="sc-festival-choice"><?php foreach(sc_festivals() as $id=>$festival): ?><option value="<?= $id ?>" <?= $config['festival']===$id?'selected':'' ?>><?= sc_e($festival[0]) ?></option><?php endforeach; ?></select></label><label class="d-block mb-3">Effect level<select class="form-select" name="intensity"><?php foreach(['low'=>'Gentle','medium'=>'Balanced','high'=>'Lively'] as $id=>$label): ?><option value="<?= $id ?>" <?= $config['intensity']===$id?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="d-block mb-3">Custom greeting (optional)<input class="form-control" name="greeting" maxlength="160" value="<?= sc_e(sc_public_setting('festive_greeting','')) ?>" placeholder="Leave blank for the festival greeting"></label><div class="d-flex flex-wrap gap-2"><button class="btn btn-primary">Save festive mode</button><a id="sc-festival-preview" class="btn btn-outline-primary" target="_blank" rel="noopener" href="<?= sc_url('?festive_preview='.$config['festival']) ?>">Preview without publishing</a></div></form></div><div class="col-lg-5"><div class="card p-4"><h2 class="h5">What visitors will see</h2><ul><li><strong>Diwali:</strong> glowing diyas and a bottom launcher that sends up a colourful sky rocket.</li><li><strong>Holi:</strong> click open space on the page for a colour splash.</li><li><strong>Eid / Bakr Eid / Ramadan:</strong> lantern and crescent decorations with golden stars.</li><li><strong>Christmas:</strong> gentle snow and festive stars.</li><li><strong>Dussehra and other celebrations:</strong> warm petals or confetti.</li><li><strong>New Year:</strong> celebratory sky rockets.</li></ul><p>Visitors can pause effects. Reduced-motion preferences are respected. Links, forms and shopping controls continue to work. Effects are limited to the homepage and run without sound.</p></div></div></div><script>document.getElementById('sc-festival-choice').addEventListener('change',e=>{const url=new URL(document.getElementById('sc-festival-preview').href);url.searchParams.set('festive_preview',e.target.value);document.getElementById('sc-festival-preview').href=url.href;});</script><?php admin_console_close(); ?>
